import { pool, queryOne, type Row } from "./db";
import { COMPARE_COST } from "./tokens";

export type CompareKind = "curated" | "custom";

export interface CompareAccess {
  ok: boolean;
  freshCharge: boolean;
  balance: number;
  reason?: "empty";
}

// Buka akses hasil compare: gratis jika pasangan ini sudah pernah dibuka user,
// selain itu potong COMPARE_COST token + catat riwayat. Idempotent per (user, kind, ref).
export async function ensureCompareAccess(
  userId: number,
  kind: CompareKind,
  refA: string,
  refB: string,
  summary: string,
): Promise<CompareAccess> {
  const seen = await queryOne<Row>(
    `SELECT id FROM compare_history WHERE user_id = ? AND kind = ? AND ref_a = ? AND ref_b = ?`,
    [userId, kind, refA, refB],
  );
  const wallet = await queryOne<Row>(`SELECT balance FROM wallets WHERE user_id = ?`, [userId]);
  const balance = Number(wallet?.balance ?? 0);
  if (seen) return { ok: true, freshCharge: false, balance };

  if (balance < COMPARE_COST) {
    return { ok: false, freshCharge: false, balance, reason: "empty" };
  }

  const conn = await pool.getConnection();
  try {
    await conn.beginTransaction();
    const [upd] = await conn.query(
      `UPDATE wallets SET balance = balance - ? WHERE user_id = ? AND balance >= ?`,
      [COMPARE_COST, userId, COMPARE_COST],
    );
    const affected = (upd as { affectedRows?: number }).affectedRows ?? 0;
    if (affected === 0) {
      await conn.rollback();
      return { ok: false, freshCharge: false, balance, reason: "empty" };
    }
    await conn.query(
      `INSERT INTO compare_history (user_id, kind, ref_a, ref_b, summary, cost)
       VALUES (?, ?, ?, ?, ?, ?)`,
      [userId, kind, refA, refB, summary.slice(0, 255), COMPARE_COST],
    );
    await conn.commit();
    return { ok: true, freshCharge: true, balance: balance - COMPARE_COST };
  } catch (err) {
    await conn.rollback();
    // Balapan request: riwayat sudah ada → anggap sudah terbuka, tanpa potong ulang.
    if ((err as { errno?: number }).errno === 1062) {
      const w = await queryOne<Row>(`SELECT balance FROM wallets WHERE user_id = ?`, [userId]);
      return { ok: true, freshCharge: false, balance: Number(w?.balance ?? 0) };
    }
    throw err;
  } finally {
    conn.release();
  }
}
